export type Cell = [number, number];

// --- Neighbourhood topology: which cells are adjacent on the unbounded grid ---

function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  return x === otherX && y === otherY;
}

function neighboursOf([x, y]: Cell): Cell[] {
  const offsets = [-1, 0, 1];
  return offsets.flatMap((dx) =>
    offsets
      .filter((dy) => !(dx === 0 && dy === 0))
      .map((dy): Cell => [x + dx, y + dy]),
  );
}

function livingNeighbourCount(cell: Cell, livingCells: Cell[]): number {
  const neighbourhood = neighboursOf(cell);
  return livingCells.filter((other) =>
    neighbourhood.some((neighbour) => isSameCell(neighbour, other)),
  ).length;
}

// --- Vitality policy: how a living neighbour count decides life ---

const MIN_NEIGHBOURS_TO_SURVIVE = 2;
const MAX_NEIGHBOURS_TO_SURVIVE = 3;

function survivesWith(livingNeighbours: number): boolean {
  return (
    livingNeighbours >= MIN_NEIGHBOURS_TO_SURVIVE &&
    livingNeighbours <= MAX_NEIGHBOURS_TO_SURVIVE
  );
}

const NEIGHBOURS_TO_REPRODUCE = 3;

function isBornWith(livingNeighbours: number): boolean {
  return livingNeighbours === NEIGHBOURS_TO_REPRODUCE;
}

// --- Generation orchestration ---

function isLiving(cell: Cell, livingCells: Cell[]): boolean {
  return livingCells.some((other) => isSameCell(cell, other));
}

// Only dead cells touching a living cell can be born, so the infinite plane
// never has to be enumerated.
function deadNeighboursOf(livingCells: Cell[]): Cell[] {
  return livingCells
    .flatMap(neighboursOf)
    .filter((cell) => !isLiving(cell, livingCells));
}

export function nextGeneration(livingCells: Cell[]): Cell[] {
  const survivors = livingCells.filter((cell) =>
    survivesWith(livingNeighbourCount(cell, livingCells)),
  );
  const births = deadNeighboursOf(livingCells).filter((cell) =>
    isBornWith(livingNeighbourCount(cell, livingCells)),
  );
  return [...survivors, ...births];
}

